import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs:
        return 0
    times = sorted({t for start, end, _pay in jobs for t in (start, end)})
    index = {t: i for i, t in enumerate(times)}
    n = len(times)
    graph = [[] for _ in range(n)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        graph[u].append([v, cap, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)
    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    inf = 10**18
    pi = [inf] * n
    pi[0] = 0
    for u in range(n):
        pu = pi[u]
        if pu >= inf:
            continue
        for v, cap, cost, _rev in graph[u]:
            if cap and pi[v] > pu + cost:
                pi[v] = pu + cost

    sink = n - 1
    sent = 0
    total = 0
    while sent < k:
        dist = [inf] * n
        dist[0] = 0
        parent = [(-1, -1)] * n
        heap = [(0, 0)]
        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            pu = pi[u]
            for ei, (v, cap, cost, _rev) in enumerate(graph[u]):
                if cap <= 0:
                    continue
                nd = d + cost + pu - pi[v]
                if nd < dist[v]:
                    dist[v] = nd
                    parent[v] = (u, ei)
                    heapq.heappush(heap, (nd, v))
        if dist[sink] >= inf:
            break
        for i in range(n):
            if dist[i] < inf:
                pi[i] += dist[i]
        bottleneck = k - sent
        v = sink
        while v != 0:
            u, ei = parent[v]
            cap = graph[u][ei][1]
            if cap < bottleneck:
                bottleneck = cap
            v = u
        unit = 0
        v = sink
        while v != 0:
            u, ei = parent[v]
            edge = graph[u][ei]
            unit += edge[2]
            edge[1] -= bottleneck
            graph[v][edge[3]][1] += bottleneck
            v = u
        sent += bottleneck
        total += bottleneck * unit
    return -total
